head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[$p > M > deleteSubmission]<br/>파라미터에 해당하는 Submission 을 삭제합니다.",
    "validation" : [
        "submissionId(필수) 파라미터로 삭제할 Submission 의 ID 를 설정할 수 있어야 합니다.",
        "삭제 성공 시 삭제한 Submission 객체를 반환해야 합니다.",
        "submissionId 파라미터에 해당하는 Submission 이 존재하지 않으면 null 값을 반환해야 합니다."
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.btn_deleteSubmission_onclick = function () {
    var scenario = par_scenario.getValue();

    // 이전 시나리오에서 남아있을 수 있는 Process Message 정리
    $p.hideProcessMessage();
    dlt_userList.removeAll();

    if (scenario === "1") {
        // 시나리오 1 : 정상 삭제 - 생성 후 삭제, 삭제한 객체 반환 + getSubmission null 확인
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 1 : 정상 삭제 ──");

        var submissionInfo = {
            "id" : "sbm_test",
            "action" : "/data/$p_createSubmission_userList.json",
            "target" : 'data:json,[{"id":"dlt_userList"}]',
            "method" : "post",
            "mediatype" : "application/json"
        };
        $p.createSubmission(submissionInfo);

        var beforeSbm = $p.getSubmission("sbm_test");
        var beforeType = (beforeSbm === null) ? "null" : (typeof beforeSbm);

        var deleted = $p.deleteSubmission("sbm_test");
        var deletedType = (deleted === null) ? "null" : (typeof deleted);

        var afterSbm = $p.getSubmission("sbm_test");
        var afterType = (afterSbm === null) ? "null" : (typeof afterSbm);

        wf_body_bottom.getObj("scwin").setReturnValue(
            "createSubmission 후 getSubmission 반환 타입 : " + beforeType +
            " -> deleteSubmission 반환 : " + deletedType +
            " / 삭제 후 getSubmission 반환 : " + afterType
        );
    } else if (scenario === "2") {
        // 시나리오 2 : 삭제 후 executeSubmission 시도 - 동작하지 않음 확인
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 2 : 삭제 후 executeSubmission 시도 ──");

        var submissionInfo2 = {
            "id" : "sbm_exec_after_delete",
            "action" : "/data/$p_createSubmission_userList.json",
            "target" : 'data:json,[{"id":"dlt_userList"}]',
            "method" : "post",
            "mediatype" : "application/json",
            "submitDoneHandler" : function (e) {
                // 삭제 후에는 호출되면 안됨
                wf_body_bottom.getObj("scwin").setReturnValue("submitDoneHandler 호출됨 (삭제 실패)");
                $p.hideProcessMessage();
            }
        };
        $p.createSubmission(submissionInfo2);

        // 삭제
        $p.deleteSubmission("sbm_exec_after_delete");

        // 삭제된 submissionId 로 executeSubmission 호출
        $p.executeSubmission("sbm_exec_after_delete");

        // 일정 시간 후 데이터 미로드 확인
        $p.setTimeout(function () {
            var rowCount = dlt_userList.getRowCount();
            wf_body_bottom.getObj("scwin").setReturnValue("삭제된 submissionId 로 executeSubmission 호출 시 미동작 확인");
            wf_body_bottom.getObj("scwin").setReturnValue("dlt_userList.getRowCount() : " + rowCount);
        }, "chk_exec_after_delete", 500);
    } else if (scenario === "3") {
        // 시나리오 3 : 존재하지 않는 ID 삭제 -> null 반환
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 3 : 존재하지 않는 ID 삭제 ──");

        var result = $p.deleteSubmission("not_exists");
        var resultType = (result === null) ? "null" : (typeof result);

        wf_body_bottom.getObj("scwin").setReturnValue("deleteSubmission('not_exists') -> " + resultType);
    }
};
